import functools

def _parse(v):
    core = v.split('+', 1)[0]
    if '-' in core:
        main, pre = core.split('-', 1)
    else:
        main, pre = core, None
    major, minor, patch = (int(x) for x in main.split('.'))
    pre_ids = pre.split('.') if pre is not None else None
    return (major, minor, patch, pre_ids)

def _cmp_identifier(a, b):
    a_num = a.isdigit()
    b_num = b.isdigit()
    if a_num and b_num:
        ai, bi = int(a), int(b)
        return (ai > bi) - (ai < bi)
    if a_num and not b_num:
        return -1
    if not a_num and b_num:
        return 1
    return (a > b) - (a < b)

def _compare(v1, v2):
    a_major, a_minor, a_patch, a_pre = _parse(v1)
    b_major, b_minor, b_patch, b_pre = _parse(v2)
    for x, y in ((a_major, b_major), (a_minor, b_minor), (a_patch, b_patch)):
        if x != y:
            return -1 if x < y else 1
    if a_pre is None and b_pre is None:
        return 0
    if a_pre is None and b_pre is not None:
        return 1
    if a_pre is not None and b_pre is None:
        return -1
    for ai, bi in zip(a_pre, b_pre):
        c = _cmp_identifier(ai, bi)
        if c != 0:
            return c
    if len(a_pre) != len(b_pre):
        return -1 if len(a_pre) < len(b_pre) else 1
    return 0

def semver_sort(versions):
    return sorted(versions, key=functools.cmp_to_key(_compare))

